import {dataTable} from './data-tables.js?v=224';
import {COUNTRY,cellName,regularCells} from './data.js?v=224';
export function enemyReport(s){
 if(s.gameMode!=='cooperative'||!s.ended)return '';
 const attacks=s.enemyAttacks||[],flights=s.enemyFlights||[],moves=s.enemyMoves||[];
 return `<h2>Bilan de Fracture</h2><p>Les attaques sont attribuées à leur cellule. La crise ci-dessous mesure la hausse effective causée par les attaques, hors tensions automatiques et réductions des joueurs.</p>${dataTable(['Cellule','Attaques exécutées','Réussies','Interceptées','Annulées','En préparation','Reports','Changements de cible','Crise ajoutée'],[...regularCells(s),3].map(cell=>{const rows=attacks.filter(p=>p.cell===cell),plans=s.plots.filter(p=>p.cell===cell);return [cell===3?'L’Architecte':cellName(cell),rows.length,rows.filter(p=>p.status==='RÉUSSIE').length,rows.filter(p=>p.status==='INTERCEPTÉE').length,plans.filter(p=>(p.resolved||p.cancelled)&&!attacks.some(a=>a.plotId===p.id)).length,plans.filter(p=>!p.resolved&&!p.cancelled).length,moves.filter(m=>m.cell===cell&&m.type==='delay').length,moves.filter(m=>m.cell===cell&&m.type==='relocation').length,rows.reduce((n,p)=>n+Math.max(0,p.crisisDelta),0)];}),'Performance des cellules ennemies')}<h2>Criminels</h2>${dataTable(['Criminel','Cellule','Statut final','Tour d’arrestation','Arrêté par','Fuites réussies','Fuites empêchées'],s.suspects.map(t=>[t.name,t.cell===3?'Commandement':cellName(t.cell),t.arrested?'Arrêté':'En liberté',t.arrestedTurn||'—',COUNTRY[t.arrestedBy]?.name||'—',flights.filter(f=>f.id===t.id&&f.status==='RÉUSSIE').length,flights.filter(f=>f.id===t.id&&f.status==='EMPÊCHÉE').length]),'Statut final des criminels')}<p>${moves.filter(m=>m.type==='flight').length} préparations de fuite durant la campagne. Une fuite encore en préparation à la fin n’est pas comptée comme réussie.</p>`;
}
